//! In-memory story index, sorted globally by (level, order).

use super::loader::{LoadError, LoadedStory, load_embedded, sort_stories};
use super::model::Level;
use std::collections::HashMap;

// Generated by build.rs. Defines `EmbeddedStory` and `STORIES`.
include!(concat!(env!("OUT_DIR"), "/story_index.rs"));

/// All embedded stories, ordered by level and story number.
#[derive(Debug, Clone, Default)]
pub struct StoryIndex {
    stories: Vec<LoadedStory>,
    by_id: HashMap<String, usize>,
}

impl StoryIndex {
    pub fn new(mut stories: Vec<LoadedStory>) -> Self {
        sort_stories(&mut stories);
        let mut by_id = HashMap::new();
        for (idx, loaded) in stories.iter().enumerate() {
            // Keep the first occurrence of a duplicate id; the validator reports
            // the duplicate as an error.
            by_id.entry(loaded.story.id.clone()).or_insert(idx);
        }
        StoryIndex { stories, by_id }
    }

    pub fn load_embedded() -> Result<Self, LoadError> {
        Ok(StoryIndex::new(load_embedded()?))
    }

    pub fn stories(&self) -> &[LoadedStory] {
        &self.stories
    }

    pub fn get(&self, id: &str) -> Option<&LoadedStory> {
        self.by_id.get(id).map(|&idx| &self.stories[idx])
    }

    pub fn level(&self, level: Level) -> impl Iterator<Item = &LoadedStory> {
        self.stories
            .iter()
            .filter(move |loaded| loaded.story.level == level)
    }

    pub fn level_count(&self, level: Level) -> usize {
        self.level(level).count()
    }

    pub fn total(&self) -> usize {
        self.stories.len()
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::collections::BTreeSet;

    /// The Level screen is fed straight from this index, so this test proves
    /// the "drop in a file and rebuild" contract: every JSON file under
    /// `assets/stories/<level>/` must be embedded by build.rs.
    #[test]
    fn embedded_index_contains_every_story_file() {
        let index = StoryIndex::load_embedded().expect("embedded stories load");
        let embedded: BTreeSet<String> = index
            .stories()
            .iter()
            .map(|loaded| loaded.story.id.clone())
            .collect();

        let root = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("assets/stories");
        let mut files = BTreeSet::new();
        for level in Level::ALL {
            let dir = root.join(level.folder());
            let entries = match std::fs::read_dir(&dir) {
                Ok(entries) => entries,
                Err(_) => continue,
            };
            for entry in entries.flatten() {
                let path = entry.path();
                if path.extension().and_then(|ext| ext.to_str()) != Some("json") {
                    continue;
                }
                let json = std::fs::read_to_string(&path).expect("read story file");
                let loaded = LoadedStory::from_json(path.to_string_lossy(), &json)
                    .expect("parse story file");
                files.insert(loaded.story.id.clone());
            }
        }

        assert_eq!(embedded, files, "build.rs must embed every story file");
        assert_eq!(index.total(), files.len());
        for level in Level::ALL {
            let expected = files
                .iter()
                .filter(|id| id.starts_with(level.folder()))
                .count();
            assert_eq!(index.level_count(level), expected, "count for {level}");
            println!("{level}: {} stories", index.level_count(level));
        }
    }
}
